param(); $root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path; $out=Join-Path $root 'tools\asset-gen\out\art-overnight-20260807-revised'; $pidPath=Join-Path $out 'run.pid'; if(Test-Path $pidPath){$id=[int](Get-Content $pidPath -Raw); if(Get-Process -Id $id -ErrorAction SilentlyContinue){Write-Output "ACTIVE PID $id"}else{Write-Output "DEAD PID $id"}}else{Write-Output 'NO PID'}; $s=Join-Path $out 'status.json'; if(Test-Path $s){$j=Get-Content $s -Raw|ConvertFrom-Json; $c=@{}; foreach($r in $j.jobs){$k=[string]$r.status;if(!$c[$k]){$c[$k]=0};$c[$k]++}; Write-Output "updated=$($j.updatedAt) current=$($j.currentJob) counts=$((($c.GetEnumerator()|%{"$($_.Name)=$($_.Value)"}) -join ', '))"}; if(Test-Path (Join-Path $out 'runner.log')){Get-Content (Join-Path $out 'runner.log') -Tail 12}
